head.script:
scwin.trigger1_onclick = function(e) {
    selectBox1.addItem("", "-전체-", 0);
    output2.setValue("addItem 후 count : " + selectBox1.getItemCount());
    selectBox1.setSelectedIndex(0);
    output3.setValue("setSelectedIndex() 후 count : " + selectBox1.getItemCount());
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 additem 버튼을 클릭한다.
    // In the browser, click the additem button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //verify 1. 최초 count : 3 / additem 후 count : 4 / setSelectedIndex() 후 count : 4  
    //First count: 3 / after additem count: 4 / after setSelectedIndex () count: 4
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('output1').getValue() == '최초 count : 3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('output2').getValue() == 'addItem 후 count : 4'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('output3').getValue() == 'setSelectedIndex() 후 count : 4'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    console.log("1:::", selectBox1.getItemCount()); //아이템 갯수 3개
    output1.setValue("최초 count : " + selectBox1.getItemCount());
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
